const agente = $('Agente JULIETA').item.json.output;
const datos = $('Datos1').last().json;
const filaAnterior = $('AñadirColumna').last().json;

const mensajeCliente = datos.Mensaje || null;

function normalizarPresupuesto(valor) {
  if (!valor) return null;
  const numeros = valor.match(/\d[\d.,]*/g);
  if (!numeros || numeros.length === 0) return null;
  const limpiar = (n) => parseFloat(n.replace(/,/g, ""));
  const valores = numeros.map(limpiar).filter((n) => !isNaN(n));
  if (valores.length === 0) return null;
  if (valores.length === 1) return Math.round(valores[0]);
  return Math.round((valores[0] + valores[1]) / 2);
}

// --- Historial: registra la interacción de ESTE turno (cliente + agente) ---
let historial = [];
try {
  historial = Array.isArray(filaAnterior.historial_conversacion)
    ? filaAnterior.historial_conversacion
    : JSON.parse(filaAnterior.historial_conversacion || "[]");
} catch (e) {
  historial = [];
}

historial.push({
  cliente: mensajeCliente,
  agente: agente.mensaje_para_cliente
});

historial = historial.slice(-3);

const update = {
  nombre: agente.nombre || null,
  destino: agente.destino || null,
  fecha: agente.fecha || null,
  fecha_regreso: agente.fecha_regreso || null,
  Adultos: agente.adultos ? parseInt(agente.adultos, 10) : null,
  Niños: agente.ninos !== "" ? parseInt(agente.ninos, 10) : null,
  Edad_ninios: agente.edad_ninios || null,
  completo: agente.todos_los_datos_completos === true,
  es_duda: agente.es_duda === true,
  pregunta_duda: agente.pregunta_duda || null,
  campo_decision: agente.campo_decision || null,
  pregunta_anterior: agente.mensaje_para_cliente || null,
  respuesta_anterior: mensajeCliente,
  historial_conversacion: JSON.stringify(historial),
  ult_mensaje: new Date().toISOString()
};

return [{ json: update }];

